{
  "tgrl": "grl TeslaModelX_Autopilot {
  actor System {
    goal ProvideSafeAssistance;          // overall safety of vehicle operation
    softGoal AccuratePerception;         // reliable detection of lanes, vehicles, obstacles
    softGoal MaintainLanePosition;       // keep vehicle centered in lane
    softGoal MaintainSafeFollowingDist;  // keep appropriate gap to lead vehicle
    softGoal IssueDriverAlerts;          // warn driver when hands off or attention needed
    softGoal EnableSpeedSetting;         // allow driver to set and hold cruising speed
  }

  actor Driver {
    goal ArriveAtDestinationSafely;      // reach destination without collision
    softGoal KeepHandsOnWheel;           // maintain physical control
    softGoal MonitorRoad;                // stay aware of traffic conditions
    softGoal ReduceWorkload;             // lower mental/physical effort while driving
    softGoal Comfort;                    // smooth ride and minimal fatigue
  }

  actor OtherRoadUsers {
    goal RemainSafeFromVehicle;          // avoid being hit by the Tesla
  }

  actor RoadWorkers {
    goal RemainSafeWhileWorking;         // stay protected from passing traffic
  }

  actor RoadAgency {
    goal EnsureClearRoadMarkings;        // maintain lane markings that Autopilot can read
  }
}",
  "goals": [
    { "id": "g1", "actor": "System", "text": "Provide safe assistance that prevents collisions for vehicle occupants and other road users." },
    { "id": "g2", "actor": "Driver", "text": "Arrive at the destination safely, without any collision." },
    { "id": "g3", "actor": "OtherRoadUsers", "text": "Remain safe from the vehicle – not be struck or endangered by its movements." },
    { "id": "g4", "actor": "System", "text": "Maintain accurate perception of lane markings, vehicles and obstacles." },
    { "id": "g5", "actor": "System", "text": "Maintain lane position reliably in all marking qualities." },
    { "id": "g6", "actor": "System", "text": "Maintain a safe following distance to the lead vehicle." },
    { "id": "g7", "actor": "System", "text": "Issue timely driver alerts when hands are off the wheel or attention lapses." },
    { "id": "g8", "actor": "Driver", "text": "Keep hands on the wheel and monitor the road continuously." },
    { "id": "g9", "actor": "Driver", "text": "Reduce driver workload and mental fatigue while using Autopilot." },
    { "id": "g10", "actor": "RoadAgency", "text": "Ensure road markings are clear and maintained so Autopilot can function correctly." }
  ]
}

